from urllib.parse import urlparse
from flask import Flask, redirect, abort

app = Flask(__name__)

def redirect_url(url):
    try:
        parsed_url = urlparse(url)
        domain = parsed_url.netloc

        if domain == "example.com":
            return redirect(url)
        else:
            abort(404)
    except Exception:
        abort(400)

# Example usage with Flask route
